@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Shipments</h1>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by destination..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p>Loading shipments...</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Description</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Description</td>
                    <td>@shipment.Destination</td>
                    <td>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">
                            @shipment.Status
                        </span>
                    </td>
                    <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                    <td>
                        <select class="form-select form-select-sm"
                                value="@shipment.Status"
                                @onchange="(e) => UpdateStatus(shipment, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<Shipment>? shipments;
    private string filterText = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        shipments?.Where(s => string.IsNullOrEmpty(filterText)
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.PickedUp => "bg-warning text-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Track Shipments</PageTitle>

<h1>Track Your Shipments</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number..."
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchByTracking">Search</button>
        </div>
    </div>
</div>

@if (searchedShipment is not null)
{
    <div class="card mb-4">
        <div class="card-header">
            <strong>@searchedShipment.TrackingNumber</strong> — @searchedShipment.Description
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-3">Origin</dt>
                <dd class="col-sm-9">@searchedShipment.Origin</dd>
                <dt class="col-sm-3">Destination</dt>
                <dd class="col-sm-9">@searchedShipment.Destination</dd>
                <dt class="col-sm-3">Status</dt>
                <dd class="col-sm-9">
                    <span class="badge @GetStatusBadgeClass(searchedShipment.Status)">
                        @searchedShipment.Status
                    </span>
                </dd>
                <dt class="col-sm-3">Estimated Delivery</dt>
                <dd class="col-sm-9">
                    @(searchedShipment.EstimatedDelivery?.ToString("MMMM dd, yyyy") ?? "TBD")
                </dd>
            </dl>
        </div>
    </div>
}
else if (searchPerformed)
{
    <div class="alert alert-warning">No shipment found with that tracking number.</div>
}

<h2 class="mt-4">My Shipments</h2>

@if (myShipments is null)
{
    <p>Loading your shipments...</p>
}
else if (myShipments.Count == 0)
{
    <p class="text-muted">You have no shipments.</p>
}
else
{
    <div class="row">
        @foreach (var shipment in myShipments)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@shipment.TrackingNumber</h5>
                        <p class="card-text">@shipment.Description</p>
                        <p class="card-text">
                            <strong>To:</strong> @shipment.Destination<br />
                            <strong>Status:</strong>
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span><br />
                            <strong>Est. Delivery:</strong>
                            @(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")
                        </p>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private Shipment? searchedShipment;
    private bool searchPerformed;
    private List<Shipment>? myShipments;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.Identity?.Name ?? string.Empty;
        myShipments = await ShipmentService.GetShipmentsForCustomerAsync(email);
    }

    private async Task SearchByTracking()
    {
        searchPerformed = true;
        searchedShipment = null;
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            searchedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await SearchByTracking();
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.PickedUp => "bg-warning text-dark",
        _ => "bg-secondary"
    };
}

